insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g2_ela_v1'
from (values
('110.4.b.2.A.iii',3,'Say "plate." Change /p/ to /s/. What word do you hear?','["slate", "plant", "plane", "spate"]'::jsonb,0,'Plate with /s/ in place of /p/ is slate.','original'),
('110.4.b.2.A.iii',3,'Say "stamp." Take away /t/. What word is left?','["tamp", "samp", "ampt", "stap"]'::jsonb,1,'Without /t/ you say samp.','original'),
('110.4.b.2.A.iv',3,'Say "block." Change /l/ to /r/. What word do you say?','["black", "bleak", "brock", "blink"]'::jsonb,2,'Replacing l with r gives brock.','original'),
('110.4.b.2.B.i',3,'Which word has a variant vowel sound like "oo" in "moon"?','["spot", "sport", "spin", "spoon"]'::jsonb,3,'Spoon has the oo sound.','original'),
('110.4.b.2.B.i',3,'Which word has a trigraph at the beginning?','["three", "thin", "that", "then"]'::jsonb,0,'Three begins with the three-letter blend thr.','original'),
('110.4.b.2.B.ii',3,'Which word has a silent letter?','["kind", "knife", "kit", "king"]'::jsonb,1,'The k is silent in knife.','original'),
('110.4.b.2.B.ii',3,'Which word has a silent "g"?','["goat", "gift", "gnat", "game"]'::jsonb,2,'The g is silent in gnat.','original'),
('110.4.b.2.B.iii',3,'Which word has a closed syllable?','["motor", "tiger", "paper", "pocket"]'::jsonb,3,'The first syllable in pocket is closed.','original'),
('110.4.b.2.B.iii',3,'Which word has a VCe syllable?','["bake", "bar", "bat", "bag"]'::jsonb,0,'Bake follows the vowel-consonant-e pattern.','original'),
('110.4.b.2.B.iv',3,'The contraction for "do not" is...','["dont", "don''t", "do''nt", "d''not"]'::jsonb,1,'Don''t uses an apostrophe for the missing o.','original'),
('110.4.b.2.B.v',3,'How can you split the word "rabbit" into syllables?','["r and abbit", "ra and bbit", "rab and bit", "rabb and it"]'::jsonb,2,'Rabbit splits between the two b''s.','original'),
('110.4.b.2.B.vi',3,'What does the prefix un- mean in "unlock"?','["more", "before", "again", "not or opposite of"]'::jsonb,3,'Un- means not.','original'),
('110.4.b.2.B.vi',3,'What does the prefix re- mean in "redo"?','["again", "after", "not", "under"]'::jsonb,0,'Re- means again.','original'),
('110.4.b.2.B.vii',3,'Which is a word readers see often?','["zibble", "would", "thrang", "plomp"]'::jsonb,1,'Would is a high-frequency word.','original'),
('110.4.b.2.C.iii',3,'Which contraction is spelled correctly?','["can''tt", "ca''nt", "can''t", "cant"]'::jsonb,2,'Can''t has the apostrophe after n.','original'),
('110.4.b.3.A',2,'Which tool tells you how to say a word and what it means?','["a map", "a calendar", "a ruler", "a dictionary"]'::jsonb,3,'A dictionary gives pronunciation and meaning.','original'),
('110.4.b.3.A',3,'A glossary in a book is found...','["at the back and lists important words", "inside a picture", "on the cover", "next to the title"]'::jsonb,0,'A glossary explains key words.','original'),
('110.4.b.3.B',3,'"The huge elephant stomped. It was gigantic." What does gigantic mean?','["very small", "very big", "very quiet", "very pretty"]'::jsonb,1,'The sentence says huge.','original'),
('110.4.b.3.B',3,'"Mia was famished after the long hike, so she ate three sandwiches." What does famished mean?','["very sleepy", "very cold", "very hungry", "very happy"]'::jsonb,2,'The sandwiches show she was hungry.','original'),
('110.4.b.3.C',2,'What does the suffix -ful mean in "careful"?','["not", "without", "again", "full of"]'::jsonb,3,'-ful means full of.','original'),
('110.4.b.3.C',3,'What does the suffix -less mean in "hopeless"?','["without", "full of", "again", "more"]'::jsonb,0,'-less means without.','original'),
('110.4.b.3.C',3,'What does the prefix dis- mean in "disagree"?','["more", "not", "before", "again"]'::jsonb,1,'Dis- means not.','original'),
('110.4.b.3.D',3,'Which word is a synonym for "big"?','["slow", "tiny", "large", "quiet"]'::jsonb,2,'Large means the same as big.','original'),
('110.4.b.3.D',3,'Which word is an antonym of "hot"?','["warm", "sunny", "boiling", "cold"]'::jsonb,3,'Cold is the opposite of hot.','original'),
('110.4.b.3.D',3,'Which pair are homophones?','["two, too", "two, ten", "too, tub", "to, go"]'::jsonb,0,'Two and too sound alike.','original'),
('110.4.b.3.D',3,'"I need to check the bark of the tree." Bark here means...','["a ship", "the rough outside of a tree", "a dog sound", "a song"]'::jsonb,1,'Bark can mean tree covering.','original'),
('110.4.b.6.A',2,'Why might you read a book of animal facts before a zoo trip?','["to draw a car", "to hear a rhyme", "to learn about the animals", "to practice jumping"]'::jsonb,2,'The purpose is to learn.','original'),
('110.4.b.6.B',3,'You are about to read about volcanoes. Which question helps?','["What is my shoe size?", "Why is the grass green?", "Who won the race?", "What makes a volcano erupt?"]'::jsonb,3,'It fits the topic.','original'),
('110.4.b.6.C',3,'The title is "The Snowy Day." The cover shows a boy in boots. What do you predict?','["the boy plays in the snow", "the boy bakes in the sun", "the boy flies a plane", "the boy swims in a pool"]'::jsonb,0,'The cover and title give clues.','original'),
('110.4.b.6.D',3,'"The sky was a deep purple as the sun melted into the hills." What do you picture?','["a rainstorm", "a sunset", "a sunrise at noon", "a snowfall"]'::jsonb,1,'The words describe sunset.','original'),
('110.4.b.6.E',3,'A story about moving to a new school reminds you of your first day. This is...','["a glossary", "a prediction", "a connection", "a rhyme"]'::jsonb,2,'You linked it to your life.','original'),
('110.4.b.6.F',3,'Sam grabs a towel and runs to the lake. What can you infer?','["He is cooking.", "He is sleeping.", "He is reading.", "He plans to swim."]'::jsonb,3,'The towel and lake suggest swimming.','original'),
('110.4.b.6.G',3,'Read: "Seeds need water, light, and soil to grow." What is the key idea?','["what seeds need to grow", "why the sky is blue", "how to build a house", "what dogs eat"]'::jsonb,0,'The sentence names needs.','original'),
('110.4.b.6.H',3,'One page says frogs lay eggs in water. Another says tadpoles breathe with gills. What can you conclude?','["frogs live only on land", "frogs start life in water", "frogs never lay eggs", "tadpoles can not swim"]'::jsonb,1,'Combining facts shows water is first.','original'),
('110.4.b.6.I',3,'You read a paragraph and are confused. What should you try?','["skip to the end", "guess every word", "reread it and think about what it says", "close the book"]'::jsonb,2,'Rereading helps.','original'),
('110.4.b.7.A',2,'A story about a lost puppy makes you think of your pet. What is this?','["a title", "a rhyme", "a heading", "a personal connection"]'::jsonb,3,'You linked it to your life.','original'),
('110.4.b.7.B',3,'Which is a good brief comment about a book?','["I liked how the story showed friendship.", "Book.", "It has pages.", "I read."]'::jsonb,0,'A comment gives an idea.','original'),
('110.4.b.7.C',3,'Why did the child cry? "Jo cried because her kite broke." Where is the evidence?','["in the picture frame", "in the sentence about the kite", "in the title only", "on the page number"]'::jsonb,1,'The sentence tells the reason.','original'),
('110.4.b.7.D',3,'Which is the best paraphrase of "The bright sun warmed the whole village"?','["The sun was cold.", "The sun left the village.", "The sun made the village warm.", "The village was dark."]'::jsonb,2,'A paraphrase keeps the meaning.','original'),
('110.4.b.7.D',3,'When you retell a story, you should include...','["only the title", "only the characters'' names", "only the ending", "the beginning, middle, and end"]'::jsonb,3,'A retell has the key parts.','original'),
('110.4.b.8.A',3,'A boy keeps trying to ride a bike and finally succeeds. What is the theme?','["never give up", "riding is easy", "bikes are red", "boys are fast"]'::jsonb,0,'The theme is perseverance.','original'),
('110.4.b.8.B',3,'Lila is nervous but still speaks to the class. What does this show?','["she is bored", "she is brave", "she is lazy", "she is angry"]'::jsonb,1,'Her action shows bravery.','original'),
('110.4.b.8.C',3,'In a story, the problem is solved at the end. This part is the...','["setting", "character", "resolution", "title"]'::jsonb,2,'The resolution solves the problem.','original'),
('110.4.b.8.D',3,'Why is the setting "a dark cave" important to a scary story?','["it shows the page number", "it tells the author''s name", "it makes the story short", "it adds mood and suspense"]'::jsonb,3,'Setting affects the feeling.','original'),
('110.4.b.9.A',3,'A story where animals talk and a lesson is taught is a...','["fable", "biography", "recipe", "map"]'::jsonb,0,'Fables have morals.','original'),
('110.4.b.9.A',3,'A story that starts "Once upon a time" and has magic is a...','["science book", "fairy tale", "news article", "dictionary"]'::jsonb,1,'Fairy tales often include magic.','original'),
('110.4.b.9.B',3,'A poem is shaped like a tree on the page. What does this do?','["hides the poem", "makes it a recipe", "helps show the topic", "changes the rhyme"]'::jsonb,2,'Shape poems show the subject.','original'),
('110.4.b.9.C',3,'In a play, the words the characters say are called...','["setting", "prefixes", "plot", "dialogue"]'::jsonb,3,'Dialogue is spoken words.','original'),
('110.4.b.9.D.i',3,'A text says, "Owls hunt at night. They have great eyesight. They hear small sounds." What is the central idea?','["how owls hunt", "a day at school", "how cars work", "how to bake"]'::jsonb,0,'All sentences are about owls hunting.','original'),
('110.4.b.9.D.ii',3,'Where would you look to find where a section on "Habitats" begins?','["the cover only", "the table of contents", "the glossary only", "the last word"]'::jsonb,1,'The table of contents lists sections.','original'),
('110.4.b.9.D.iii',3,'A text explains that because it rained, the grass grew. The text structure is...','["dialogue", "compare and contrast", "cause and effect", "rhyme"]'::jsonb,2,'It shows why something happened.','original'),
('110.4.b.9.E.i',3,'An ad says, "Buy our juice! It is the best!" What does it want you to do?','["read a poem", "go to sleep", "plant a tree", "buy the juice"]'::jsonb,3,'The ad tries to persuade you.','original'),
('110.4.b.9.E.ii',3,'Which sentence is a fact?','["A giraffe is the tallest land animal.", "Giraffes are the prettiest animals.", "Giraffes should be pets.", "Giraffes are boring."]'::jsonb,0,'A fact can be proven.','original'),
('110.4.b.9.E.ii',3,'Which sentence is an opinion?','["Pizza is round.", "Pizza is the yummiest food.", "Pizza is baked in an oven.", "Pizza has cheese."]'::jsonb,1,'An opinion tells a feeling.','original'),
('110.4.b.10.A',3,'Why did the author write a book called "How to Plant a Garden"?','["to sell toys", "to scare readers", "to teach readers", "to tell a joke"]'::jsonb,2,'The purpose is to inform.','original'),
('110.4.b.10.B',3,'A book lists steps in order. This structure helps the author...','["tell a ghost story", "trick readers", "write a poem", "teach how to do something"]'::jsonb,3,'Steps explain a process.','original'),
('110.4.b.10.C',3,'What does a diagram with labels help the reader do?','["understand the parts of something", "guess", "forget the text", "skip pages"]'::jsonb,0,'Labels name parts.','original'),
('110.4.b.10.D',3,'"The wind whispered through the trees." This uses...','["a number", "figurative language", "a date", "a list"]'::jsonb,1,'Wind does not really whisper.','original'),
('110.4.b.10.D',3,'Which phrase is figurative?','["a big box", "a red pencil", "as busy as a bee", "ten dogs"]'::jsonb,2,'It compares a person to a bee.','original'),
('110.4.b.10.E',3,'"I felt happy when I won." Which point of view is this?','["none", "second person", "third person", "first person"]'::jsonb,3,'It uses I.','original'),
('110.4.b.10.E',3,'"She felt happy when she won." Which point of view is this?','["third person", "first person", "none", "second person"]'::jsonb,0,'It uses she.','original'),
('110.4.b.10.F',3,'The poem says "Run, run, run, as fast as you can." What is repeated?','["the word as", "the word run", "the word can", "the word fast"]'::jsonb,1,'Run appears three times.','original'),
('110.4.b.11.B.i',3,'Which sentence is a good topic sentence for a paragraph about dogs?','["It is Monday.", "I have shoes.", "Dogs make great pets.", "Dogs."]'::jsonb,2,'A topic sentence tells the main idea.','original'),
('110.4.b.11.B.ii',3,'Which detail best supports "Dogs make great pets"?','["Pizza has cheese.", "Cats are small.", "The sky is blue.", "They are loyal and friendly."]'::jsonb,3,'Details back up the main idea.','original'),
('110.4.b.11.C',3,'Which revision adds a good detail to "The boy ran."?','["The tall boy ran across the muddy field.", "The boy ran ran.", "The boy.", "Ran boy the."]'::jsonb,0,'Adding details improves a sentence.','original'),
('110.4.b.11.D.i',2,'Which sentence has the verb that agrees?','["The bird sing.", "The birds sing.", "The birds sings.", "The bird are singing."]'::jsonb,1,'Plural subjects use sing.','original'),
('110.4.b.11.D.ii',3,'Which sentence uses the future tense?','["We play now.", "We have played.", "We will play tomorrow.", "We played yesterday."]'::jsonb,2,'Will play is future.','original'),
('110.4.b.11.D.ii',3,'Which word completes the sentence in the past? "Yesterday, I ___ to the store."','["will walk", "walking", "walk", "walked"]'::jsonb,3,'Walked is past tense.','original'),
('110.4.b.11.D.iii',3,'Which word is a common noun?','["city", "Austin", "Monday", "Texas"]'::jsonb,0,'City is a general noun.','original'),
('110.4.b.11.D.iii',3,'Which shows the plural of "child"?','["childs", "children", "childes", "childen"]'::jsonb,1,'Child has an irregular plural.','original'),
('110.4.b.11.D.iv',3,'Which sentence uses an adjective?','["Trees fall.", "The tree fell.", "The tall tree fell.", "It fell."]'::jsonb,2,'Tall describes the tree.','original'),
('110.4.b.11.D.v',3,'Which word is an adverb that tells where?','["yesterday", "happy", "slowly", "outside"]'::jsonb,3,'Outside tells where.','original'),
('110.4.b.11.D.v',3,'Which word is an adverb that tells when?','["tomorrow", "there", "softly", "quietly"]'::jsonb,0,'Tomorrow tells when.','original'),
('110.4.b.11.D.vi',3,'Which phrase is a prepositional phrase?','["ran fast", "under the table", "the red car", "big and loud"]'::jsonb,1,'A prepositional phrase begins with a preposition.','original'),
('110.4.b.11.D.vii',3,'Choose the right pronoun: "___ is my friend."','["Her", "Hers''s", "She", "Hers"]'::jsonb,2,'She is a subject pronoun.','original'),
('110.4.b.11.D.vii',3,'Which is a possessive pronoun?','["then", "they", "them", "their"]'::jsonb,3,'Their shows ownership.','original'),
('110.4.b.11.D.viii',3,'Which sentence uses a coordinating conjunction to join two subjects?','["Sam and Ana ran.", "Running is fun.", "Ana ran.", "Sam ran fast."]'::jsonb,0,'And joins Sam and Ana.','original'),
('110.4.b.11.D.viii',3,'Which word is a coordinating conjunction?','["under", "but", "slowly", "tall"]'::jsonb,1,'But joins ideas.','original'),
('110.4.b.11.D.ix',3,'Which of these needs a capital letter?','["every adjective", "any verb", "the name of a month", "the word \"the\""]'::jsonb,2,'Months and days of the week are capitalized.','original'),
('110.4.b.11.D.ix',3,'Which punctuation mark ends the greeting in a friendly letter?','["a colon", "a period", "a question mark", "a comma"]'::jsonb,3,'A greeting ends with a comma.','original'),
('110.4.b.11.D.x',3,'Which is written correctly?','["I can''t go.", "I cant go.", "I ca''nt go.", "I can''t'' go."]'::jsonb,0,'Can''t uses an apostrophe.','original'),
('110.4.b.11.D.x',3,'Which sentence uses commas in a list correctly?','["I like, apples grapes and pears.", "I like apples, grapes, and pears.", "I like apples, grapes and, pears.", "I like apples grapes, and pears."]'::jsonb,1,'Commas separate items in a list.','original'),
('110.4.b.12.A',3,'Which is a good start for a personal narrative?','["Skates are made of metal.", "There are four seasons.", "Last winter, I learned to skate.", "Ice is cold."]'::jsonb,2,'A personal narrative tells about your own life.','original'),
('110.4.b.12.B',3,'A how-to paragraph about brushing teeth should include...','["a list of colors", "a joke", "a rhyme", "steps in order"]'::jsonb,3,'Procedural texts use sequence.','original'),
('110.4.b.12.C',3,'A thank-you note should include...','["a greeting, a thank you, and a closing", "a map", "just the date", "a long story only"]'::jsonb,0,'These are the parts of a note.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
